import type { Message } from "@/lib/llm";

const d = (...lines: string[]): Message[] =>
  lines.map((content, i) => ({ role: i % 2 === 0 ? "user" : "assistant", content }));

// Пять заранее подготовленных диалогов: [переписка, реальная цитата студента]
